head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//발행기관 처리자 조회
scwin.vScrenID = "ULDINS93200.xml";
scwin.ISUR_APPL_ID = "";
scwin.param1 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 처리자 조회
 ***********************************************/
scwin.ins_search = function() {
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var queryId = "";
    // 발행기관 처리자 조회 팝업이다. 
    // param1 => 발행기관 ISUR_CD 
    queryId = "lds.ins.common.select.listCorpPrcInquiry";
    //alert(queryId); 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS93200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + scwin.param1 + "&{P}param02=" + scwin.param1;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = scwin.ISUR_APPL_ID;
    scwin.arrPar[1] = "ISUR_CD";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(scwin.arrPar);
        scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] != undefined) ? scwin.arrPar[0] : "");
        //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

        scwin.ins_search();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    $c.stf.alert_error(dts_List);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    //alert('dts_List.OnLoadCompleted('+rowcount+')');

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row == 0) return;
    scwin.ISUR_APPL_ID = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_APPL_ID"); // 발행기관  신청 ID   
    if (scwin.ISUR_APPL_ID == "접수번호없음") return;
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93600", "신청인정보", "620", "410");
};
